(() => {
  const base = $node["Config"].json["SUPABASE_URL"];
  const clientId = $node["get_conversation_v2"].json["client_id"];
  const platform = $node["get_channel_identity_v2"].json["platform"];
  const channelKey = $node["get_channel_identity_v2"].json["channel_key"];
  const slug = platform === "whatsapp" ? "whatsapp_evolution" : platform;

  // Multi-account safety: select the integration row that belongs to THIS
  // conversation's channel identity, not merely the client's first row.
  // Mirrors AutoResponder_Final's inbound client_feature lookup: facebook
  // keys on config.pageId, instagram on config.instagram_account_id,
  // telegram on config.channelKey. WhatsApp Evolution is resolved
  // per-account elsewhere via get_whatsapp_number (client_id + channel_key)
  // and is not selected here.
  let keyFilter = "";
  if (platform === "facebook") keyFilter = "&config->>pageId=eq." + encodeURIComponent(channelKey || "");
  else if (platform === "instagram") keyFilter = "&config->>instagram_account_id=eq." + encodeURIComponent(channelKey || "");
  else if (platform === "telegram") keyFilter = "&config->>channelKey=eq." + encodeURIComponent(channelKey || "");

  // Fail safe: for FB/TG/IG a missing channel_key must NOT fall back to an
  // arbitrary client account — force a zero-row result instead.
  if ((platform === "facebook" || platform === "instagram" || platform === "telegram") && !channelKey) {
    keyFilter = "&id=eq.00000000-0000-0000-0000-000000000000";
  }

  return base +
    "/rest/v1/client_feature_integrations" +
    "?select=id,client_id,is_active,config,features!inner(slug)" +
    "&client_id=eq." + encodeURIComponent(clientId) +
    "&features.slug=eq." + encodeURIComponent(slug) +
    keyFilter +
    "&is_active=eq.true" +
    "&limit=1";
})()
}}

