const body = $node["Webhook"].json.body || {};
const conversation = $node["get_conversation_v2"].json || {};
const identity = $node["get_channel_identity_v2"].json || {};
const integration = $node["get_client_integration"].json || {};

const platform = String(
  identity.platform ||
  conversation.platform ||
  ""
).toLowerCase().trim();

const messageType = String(
  body.message_type || "text"
).toLowerCase().trim();

const recipient = String(identity.sender_id || "").trim();
const text = String(body.message || "");
const mediaUrl = String(body.media_url || "").trim();

if (!conversation.id) {
  throw new Error("Conversation not found");
}

if (!identity.id) {
  throw new Error("Channel identity not found");
}

if (!recipient) {
  throw new Error("Missing recipient");
}

let requestUrl = "";
let requestHeaders = {
  "Content-Type": "application/json"
};
let requestBody = {};

// =====================================================
// WHATSAPP - EVOLUTION
// =====================================================

if (platform === "whatsapp") {
  const waServer = $json || {};
  const waNumber = $node["get_whatsapp_number"].json || {};

  const instanceName = waNumber.instance_name;

  if (!instanceName) {
    throw new Error("Missing WhatsApp instance_name");
  }

  if (!waServer.base_url) {
    throw new Error("Missing WhatsApp server base_url");
  }

  if (!waServer.api_key) {
    throw new Error("Missing WhatsApp server api_key");
  }

  // Safety check:
  // the WhatsApp number must match the conversation's channel identity.
  if (
    identity.channel_key &&
    waNumber.channel_key &&
    String(identity.channel_key) !== String(waNumber.channel_key)
  ) {
    throw new Error(
      "WhatsApp channel mismatch between conversation identity and selected instance"
    );
  }

  requestHeaders.apikey = waServer.api_key;

  if (messageType === "text") {
    if (!text) {
      throw new Error("WhatsApp text message is empty");
    }

    requestUrl =
      waServer.base_url +
      "/message/sendText/" +
      encodeURIComponent(instanceName);

    requestBody = {
      number: recipient,
      text
    };
  }

  else if (messageType === "image" || messageType === "document") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    requestUrl =
      waServer.base_url +
      "/message/sendMedia/" +
      encodeURIComponent(instanceName);

    requestBody = {
      number: recipient,
      mediatype: messageType,
      mimetype: body.media_mime_type || undefined,
      media: mediaUrl,
      caption: text || ""
    };

    if (body.media_file_name) {
      requestBody.fileName = body.media_file_name;
    }
  }

  else if (messageType === "audio") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    requestUrl =
      waServer.base_url +
      "/message/sendWhatsAppAudio/" +
      encodeURIComponent(instanceName);

    requestBody = {
      number: recipient,
      audio: mediaUrl
    };
  }

  else {
    throw new Error(
      `Unsupported WhatsApp message_type: ${messageType}`
    );
  }
}

// =====================================================
// TELEGRAM
// =====================================================

else if (platform === "telegram") {
  const token =
    integration.config?.["Bot Token"] ||
    integration.config?.bot_token ||
    integration.config?.token;

  if (!token) {
    throw new Error("Missing Telegram Bot Token");
  }

  const telegramBase =
    `https://api.telegram.org/bot${token}/`;

  if (messageType === "text") {
    if (!text) {
      throw new Error("Telegram text message is empty");
    }

    requestUrl = telegramBase + "sendMessage";

    requestBody = {
      chat_id: recipient,
      text
    };
  }

  else if (messageType === "image") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    requestUrl = telegramBase + "sendPhoto";

    requestBody = {
      chat_id: recipient,
      photo: mediaUrl
    };

    if (text) {
      requestBody.caption = text;
    }
  }

  else if (messageType === "document") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    requestUrl = telegramBase + "sendDocument";

    requestBody = {
      chat_id: recipient,
      document: mediaUrl
    };

    if (text) {
      requestBody.caption = text;
    }
  }

  else if (messageType === "audio") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    const mime = String(
      body.media_mime_type || ""
    ).toLowerCase();

    const telegramPlayableAudio =
      mime === "audio/mpeg" ||
      mime === "audio/mp3" ||
      mime === "audio/mp4" ||
      mime === "audio/m4a" ||
      mime === "audio/x-m4a";

    if (telegramPlayableAudio) {
      requestUrl = telegramBase + "sendAudio";

      requestBody = {
        chat_id: recipient,
        audio: mediaUrl
      };
    } else {
      requestUrl = telegramBase + "sendDocument";

      requestBody = {
        chat_id: recipient,
        document: mediaUrl
      };
    }

    if (text) {
      requestBody.caption = text;
    }
  }

  else {
    throw new Error(
      `Unsupported Telegram message_type: ${messageType}`
    );
  }
}

// =====================================================
// FACEBOOK MESSENGER
// =====================================================

else if (platform === "facebook") {
  const pageAccessToken =
    integration.config?.["Page Access Token"] ||
    integration.config?.page_access_token;

  if (!pageAccessToken) {
    throw new Error("Missing Facebook Page Access Token");
  }

  requestUrl =
    "https://graph.facebook.com/v18.0/me/messages?access_token=" +
    encodeURIComponent(pageAccessToken);

  if (messageType === "text") {
    if (!text) {
      throw new Error("Facebook text message is empty");
    }

    requestBody = {
      recipient: {
        id: recipient
      },
      message: {
        text
      }
    };
  }

  else if (
    messageType === "image" ||
    messageType === "document" ||
    messageType === "audio"
  ) {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    let attachmentType = messageType;

    if (messageType === "document") {
      attachmentType = "file";
    }

    requestBody = {
      recipient: {
        id: recipient
      },
      message: {
        attachment: {
          type: attachmentType,
          payload: {
            url: mediaUrl,
            is_reusable: true
          }
        }
      }
    };
  }

  else {
    throw new Error(
      `Unsupported Facebook message_type: ${messageType}`
    );
  }
}

else if (platform === "instagram") {
  const igAccountId = String(
    integration.config?.instagram_account_id ||
    integration.config?.["Instagram Account ID"] ||
    ""
  ).trim();

  const igToken =
    integration.config?.page_access_token ||
    integration.config?.["Page Access Token"];

  if (!igAccountId) {
    throw new Error("Missing Instagram account ID");
  }

  if (!igToken) {
    throw new Error("Missing Instagram access token");
  }

  requestUrl =
    "https://graph.instagram.com/v25.0/" +
    encodeURIComponent(igAccountId) +
    "/messages";

  requestHeaders = {
    "Content-Type": "application/json",
    "Authorization": "Bearer " + igToken
  };

  if (messageType === "text") {
    if (!text) {
      throw new Error("Instagram text message is empty");
    }

    requestBody = {
      recipient: {
        id: recipient
      },
      message: {
        text
      }
    };
  }

  else if (messageType === "image") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    requestBody = {
      recipient: {
        id: recipient
      },
      message: {
        attachment: {
          type: "image",
          payload: {
            url: mediaUrl,
            is_reusable: true
          }
        }
      }
    };
  }

  else if (messageType === "audio") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    // EXPERIMENTAL: Instagram Messaging audio attachment by URL. Formed
    // so a live send captures Meta's real Graph API response — NOT a
    // claim that Instagram accepts it. Continues through
    // document_delivery_router's fallback to send_provider_request.
    requestBody = {
      recipient: {
        id: recipient
      },
      message: {
        attachment: {
          type: "audio",
          payload: {
            url: mediaUrl,
            is_reusable: true
          }
        }
      }
    };
  }

  else if (messageType === "document") {
    if (!mediaUrl) {
      throw new Error("Missing media_url");
    }

    // EXPERIMENTAL: Instagram Messaging has no documented "file"
    // attachment type. Formed deliberately so a live send captures
    // Meta's actual response — do NOT read it as proof of support.
    // document_delivery_router routes Instagram documents here to
    // send_provider_request, not the WA/TG/FB binary path.
    requestBody = {
      recipient: {
        id: recipient
      },
      message: {
        attachment: {
          type: "file",
          payload: {
            url: mediaUrl,
            is_reusable: true
          }
        }
      }
    };
  }

  else {
    throw new Error(
      "Instagram does not support this message type in the current Human Reply implementation"
    );
  }
}

else {
  throw new Error(`Unsupported platform: ${platform}`);
}

// =====================================================
// UNIFIED OUTPUT
// =====================================================

return [
  {
    json: {
      ...body,

      platform,

      provider:
        platform === "whatsapp"
          ? "evolution"
          : platform,

      request_method: "POST",
      request_url: requestUrl,
      request_headers: requestHeaders,
      request_body: requestBody,

      conversation_id: conversation.id,
      channel_identity_id: identity.id,
      channel_key: identity.channel_key || null,
      sender_id: recipient,

      message_type: messageType,

      media_path: body.media_path || null,
      media_mime_type: body.media_mime_type || null,
      media_file_name: body.media_file_name || null,
      media_size_bytes: body.media_size_bytes || null
    }
  }
];

const body = $node["Webhook"].json.body || {};
const identity = $node["get_channel_identity_v2"].json || {};
const waNumber = $node["get_whatsapp_number"].json || {};
const waServer = $node["get_whatsapp_server"].json || {};

const binaryMeta = $binary?.data;

if (!binaryMeta) {
  throw new Error("Missing binary.data");
}

if (!identity.sender_id) {
  throw new Error("Missing recipient sender_id");
}

if (!waNumber.instance_name) {
  throw new Error("Missing WhatsApp instance_name");
}

if (!waServer.base_url) {
  throw new Error("Missing WhatsApp server base_url");
}

if (!waServer.api_key) {
  throw new Error("Missing WhatsApp server api_key");
}

// Safety check: make sure the selected WhatsApp instance
// belongs to the current conversation's channel identity.
if (
  identity.channel_key &&
  waNumber.channel_key &&
  String(identity.channel_key) !== String(waNumber.channel_key)
) {
  throw new Error(
    "WhatsApp channel mismatch between conversation identity and selected instance"
  );
}

const buffer = await this.helpers.getBinaryDataBuffer(0, "data");

if (!buffer || !buffer.length) {
  throw new Error("Missing binary buffer");
}

const base64 = buffer.toString("base64");

return [
  {
    json: {
      request_url:
        waServer.base_url +
        "/message/sendMedia/" +
        encodeURIComponent(waNumber.instance_name),

      request_headers: {
        apikey: waServer.api_key,
        "Content-Type": "application/json"
      },

      request_body: {
        number: identity.sender_id,
        mediatype: "document",

        mimetype:
          body.media_mime_type ||
          binaryMeta.mimeType ||
          "application/octet-stream",

        caption: body.message || "",

        media: base64,

        fileName:
          body.media_file_name ||
          binaryMeta.fileName ||
          "document"
      },

      conversation_id:
        $node["get_conversation_v2"].json["id"],

      channel_identity_id:
        identity.id,

      channel_key:
        identity.channel_key || null
    }
  }
];

